style.css:
@-moz-document domain("bing.com") {
/* ? Custom Color Palette from your Image */
    :root {
        --magic-bg: #f7f3ee;          /* Soft, cozy beige background */
        --magic-search-bg: #333333;   /* Deep charcoal dark search bar */
        --magic-search-text: #ffffff; /* White text inside search */
        --magic-highlight: #fdf5c4;    /* Pastel butter-yellow label highlight */
        --magic-text-dark: #111111;   /* Script text color */
        --magic-bow-red: #801322;     /* Deep wine/maroon bow color for accents */
    }

    /* ? Main Page Background */
    body, #b_content, .hp_sw_top {
        background-color: var(--magic-bg) !important;
        background-image: none !important;
    }

    /* ? Custom Search Bar styling */
    .sb_form, #sb_form, .b_searchboxForm {
        background-color: var(--magic-search-bg) !important;
        border: 2px solid transparent !important;
        border-radius: 4px !important; /* Elegant, straighter edges like your sample */
        box-shadow: none !important;
    }

    /* Input Text inside the search bar */
    input[type="search"], #sb_form_q, .b_searchbox {
        color: var(--magic-search-text) !important;
        background-color: transparent !important;
        font-family: 'Segoe UI', Arial, sans-serif !important;
    }

    /* Change the color of search icons/mic to match the bright accents */
    .search.icon, .sw_as, .sb_form_go, .b_searchboxSubmit {
        fill: var(--magic-highlight) !important;
        color: var(--magic-highlight) !important;
    }

    /* ?️ Butter-Yellow Label Highlights (Applies to badges, small tabs, tag elements) */
    .b_attribution, .b_caption, [class*="tag"], [class*="label"], .b_factrow {
        background-color: var(--magic-highlight) !important;
        color: var(--magic-text-dark) !important;
        padding: 2px 6px !important;
        border-radius: 4px !important;
        display: inline-block !important;
    }

    /* ?️ Whimsical Typography headings (simulating your "Believe in the magic" style) */
    h1, h2, .b_algo h2 a, .hp_title {
        font-family: 'Georgia', 'Times New Roman', serif !important;
        font-style: italic !important;
        color: var(--magic-text-dark) !important;
    }

    /* ? Links and Interactivity using the deep red bow color */
    a, .b_primtxt {
        color: var(--magic-bow-red) !important;
    }
    
    a:hover {
        text-decoration: underline !important;
    }
}
